CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY,email text UNIQUE NOT NULL,password_hash text NOT NULL,name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS workspaces(id uuid PRIMARY KEY,name text NOT NULL,owner_id uuid NOT NULL REFERENCES users(id),settings jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS members(workspace_id uuid REFERENCES workspaces(id) ON DELETE CASCADE,user_id uuid REFERENCES users(id) ON DELETE CASCADE,role text NOT NULL CHECK(role IN ('owner','admin','agent','viewer')),PRIMARY KEY(workspace_id,user_id));
CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS records(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,kind text NOT NULL,data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS records_scope ON records(workspace_id,kind,created_at DESC);
CREATE TABLE IF NOT EXISTS connections(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,provider text NOT NULL,external_id text NOT NULL,name text NOT NULL,secret text NOT NULL,expires_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(provider,external_id));
CREATE TABLE IF NOT EXISTS events(id text PRIMARY KEY,provider text NOT NULL,workspace_id uuid REFERENCES workspaces(id) ON DELETE CASCADE,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS jobs(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,unique_key text UNIQUE NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'pending',attempts integer NOT NULL DEFAULT 0,error text,run_at timestamptz NOT NULL DEFAULT now(),locked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS jobs_pending ON jobs(status,run_at);
CREATE TABLE IF NOT EXISTS subscriptions(workspace_id uuid PRIMARY KEY REFERENCES workspaces(id) ON DELETE CASCADE,membership_id text UNIQUE,plan text NOT NULL DEFAULT 'free',status text NOT NULL DEFAULT 'inactive',updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS affiliates(id uuid PRIMARY KEY,user_id uuid UNIQUE NOT NULL REFERENCES users(id),code text UNIQUE NOT NULL,status text NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS referrals(workspace_id uuid PRIMARY KEY REFERENCES workspaces(id),affiliate_id uuid NOT NULL REFERENCES affiliates(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payments(id text PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),amount numeric(12,2) NOT NULL,currency text NOT NULL,status text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS commissions(id uuid PRIMARY KEY,payment_id text UNIQUE NOT NULL REFERENCES payments(id),affiliate_id uuid NOT NULL REFERENCES affiliates(id),amount numeric(12,2) NOT NULL,currency text NOT NULL,status text NOT NULL DEFAULT 'pending',available_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rate_limits(key text PRIMARY KEY,count integer NOT NULL DEFAULT 1,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS oauth_states(state_hash text PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),user_id uuid NOT NULL REFERENCES users(id),provider text NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS recovery_tokens(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS bookings(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),service_id uuid NOT NULL REFERENCES records(id),staff text NOT NULL,customer text NOT NULL,email text NOT NULL,start_at timestamptz NOT NULL,end_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'confirmed',cancel_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK(end_at > start_at));
CREATE INDEX IF NOT EXISTS bookings_slots ON bookings(workspace_id,staff,start_at,end_at);
CREATE TABLE IF NOT EXISTS audit(id uuid PRIMARY KEY,workspace_id uuid REFERENCES workspaces(id) ON DELETE CASCADE,user_id uuid REFERENCES users(id),action text NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
